  let after;try{after=await read(id)}catch{throw Error('保存結果未確認。再送せず更新してください')}
  if(after.state!==target||after.updated===before.updated)throw Error('保存結果未確認。再送せず更新してください');
  if(req.action==='complete'&&!rejected)undo.set(id,{state:before.state,updated:after.updated});else undo.delete(id);
