 const header=/^(\d{4}-\d{2}-\d{2}T[^\s·]+)\s*·\s*(?:Memo|Clarity(?:\.Voice|\.Text|\.Share)?|clarity\/(?:voice|text|share))\s*·\s*(clarity[:\-][A-Za-z0-9._:-]{3,128})(?:\s|$)/u;
