 async function inbox(){if(!cfg.inbox)throw Error('Inbox未取得');const blocks=[],cursors=new Set();let cursor='';for(let i=0;i<10;i++){const p=await api('blocks/'+cfg.inbox+'/children?page_size=100'+(cursor?'&start_cursor='+encodeURIComponent(cursor):''));if(!Array.isArray(p.results)||typeof p.has_more!=='boolean')throw Error('Inbox未取得');blocks.push(...p.results);if(!p.has_more)return extract(blocks);if(!p.next_cursor||cursors.has(p.next_cursor))throw Error('Inbox未取得');cursors.add(p.next_cursor);cursor=p.next_cursor}throw Error('Inbox全件取得未確認')}
 async function refresh(){const tasks=[];let taskErrors=0;for(const id of allowed){try{tasks.push(await read(id))}catch{taskErrors++}}let captures=[],inboxOK=false;try{captures=await inbox();inboxOK=true}catch{}return {tasks,taskErrors,captures,inboxOK,readAt:new Date().toISOString()}}
