// Explicit user-selected Clarity raw record; append to existing Self page only.
function createSelfCaptureWriter(api,cfg,bridge){
 const norm=x=>String(x||'').replace(/-/g,'').toLowerCase();const text=x=>Array.isArray(x)?x.map(t=>t.plain_text||t.text?.content||'').join(''):'';
 const marker=id=>'[YOS-Self-Clarity:'+id+']';
 async function blocks(id){let cursor='',out=[],seen=new Set();for(let i=0;i<20;i++){const p=await api('blocks/'+id+'/children?page_size=100'+(cursor?'&start_cursor='+encodeURIComponent(cursor):''));if(!Array.isArray(p.results)||typeof p.has_more!=='boolean')throw Error('正本取得未確認');out.push(...p.results);if(!p.has_more)return out;if(!p.next_cursor||seen.has(p.next_cursor))throw Error('正本取得未確認');seen.add(p.next_cursor);cursor=p.next_cursor}throw Error('正本全件取得未確認')}
 async function checkPage(){const p=await api('pages/'+cfg.self);if(norm(p.id)!==norm(cfg.self)||norm(p.parent?.data_source_id)!==norm(cfg.source)||p.archived||p.in_trash||!text(p.properties?.['やること']?.title).startsWith('Self｜外見の大解剖'))throw Error('既存外見カルテを確認できません')}
 function matches(b,id){return b.filter(x=>x.type==='paragraph'&&text(x.paragraph?.rich_text).startsWith(marker(id)+'\n'))}
 function content(c){return marker(c.id)+'\nClarity 原文（本人確認済み・実施判定なし）\n'+c.at+'\n'+c.raw}
 async function save(q){if(typeof q.id!=='string'||!/^clarity[:\-][A-Za-z0-9._:-]{3,128}$/.test(q.id)||typeof q.raw!=='string'||typeof q.at!=='string')throw Error('記録候補不正');await checkPage();const data=await bridge.refresh();if(!data.inboxOK)throw Error('Inbox未取得');const c=data.captures.find(x=>x.id===q.id);if(!c||c.raw!==q.raw||c.at!==q.at)throw Error('原文が変更されました。更新してください');const expected=content(c);const prior=matches(await blocks(cfg.self),q.id);if(prior.length){if(prior.length===1&&text(prior[0].paragraph.rich_text)===expected)return {saved:true,duplicate:true,id:q.id};throw Error('同一IDの記録に不一致。書込停止')}
 // No blind retry. If the response is lost, check the exact existing marker.
 try{await api('blocks/'+cfg.self+'/children','PATCH',{children:[{object:'block',type:'paragraph',paragraph:{rich_text:[{type:'text',text:{content:expected}}]}}]})}catch{}
 const found=matches(await blocks(cfg.self),q.id);if(found.length!==1||text(found[0].paragraph.rich_text)!==expected)throw Error('保存結果未確認。再送せず正本を確認してください');return {saved:true,duplicate:false,id:q.id};}
 return {save};
}
if(typeof module!=='undefined')module.exports={createSelfCaptureWriter};

// Resolve existing Notion sources on the device, not in a public code file.
function createSelfDiscovery(api){
 const titles={self:'Self｜外見の大解剖・似合わせカルテ作成',plan:'イケメン計画90day｜基礎から自然に垢抜ける',body:'イケメン攻略本｜身体・顔の未測定サイズを測る',basic:'90day｜朝・夜の基本ルーティンを試す',day30:'90day｜Day30｜肌・眉・体型・費用を比較',day60:'90day｜Day60｜習慣の続きやすさを見直す',day90:'90day｜Day90｜イケメン計画の最終レビュー',skin:'皮膚科でニキビ・毛穴詰まりの保険診療と処方薬を相談',inbox:'YOS Inbox'};
 const labels=['肩幅','胸囲','腹囲','ウエスト','ヒップ','首周り','上腕囲','太もも','ふくらはぎ','股下','顔の縦幅','顔の横幅'];
 const norm=x=>String(x||'').replace(/-/g,'').toLowerCase(),goodId=x=>/^[a-f0-9]{32}$/.test(norm(x));const text=x=>Array.isArray(x)?x.map(t=>t.plain_text||t.text?.content||'').join(''):'';
 const pageTitle=p=>text(p.properties?.['やること']?.title)||Object.values(p.properties||{}).filter(x=>x.type==='title'||Array.isArray(x.title)).map(x=>text(x.title)).join('');
 async function search(title){let c='',out=[],seen=new Set();for(let i=0;i<8;i++){const p=await api('search','POST',{query:title,filter:{value:'page',property:'object'},page_size:100,...(c?{start_cursor:c}:{})});if(!Array.isArray(p.results)||typeof p.has_more!=='boolean')throw Error('Notion検索未確認');out.push(...p.results.filter(x=>x.object==='page'&&!x.archived&&!x.in_trash&&(pageTitle(x)===title||(title==='YOS Inbox'&&pageTitle(x)==='📥 YOS Inbox'))&&goodId(x.id)));if(!p.has_more)return out;if(!p.next_cursor||seen.has(p.next_cursor))throw Error('Notion検索未確認');seen.add(p.next_cursor);c=p.next_cursor}throw Error('Notion検索上限')}
 async function get(key,source=null){const list=(await search(titles[key])).filter(x=>!source||norm(x.parent?.data_source_id)===norm(source));if(list.length!==1)throw Error('正本が一意に確認できません');return list[0]}
 async function blocks(id){let c='',out=[],seen=new Set();for(let i=0;i<20;i++){const p=await api('blocks/'+id+'/children?page_size=100'+(c?'&start_cursor='+encodeURIComponent(c):''));if(!Array.isArray(p.results)||typeof p.has_more!=='boolean')throw Error('正本本文未確認');out.push(...p.results);if(!p.has_more)return out;if(!p.next_cursor||seen.has(p.next_cursor))throw Error('正本本文未確認');seen.add(p.next_cursor);c=p.next_cursor}throw Error('正本本文取得上限')}
 const date=x=>/^\d{4}-\d{2}-\d{2}$/.test(x||'')&&Number.isFinite(Date.parse(x))&&new Date(x).toISOString().slice(0,10)===x?x:'';
 const due=p=>date(p?.properties?.['期限']?.date?.start?.slice(0,10));const offset=(d,n)=>new Date(Date.parse(d)+n*86400000).toISOString().slice(0,10);
 function dates(p){const end=due(p.plan);if(!end||due(p.day90)!==end)return null;const start=offset(end,-89);if(due(p.day30)!==offset(start,29)||due(p.day60)!==offset(start,59))return null;return {start,end,day30:due(p.day30),day60:due(p.day60),day90:end}}
 async function measurements(page){const bs=await blocks(page.id);for(const b of bs){if(b.type!=='table'||!b.has_children||!goodId(b.id))continue;const rows=await blocks(b.id),h=rows[0];if(h?.type!=='table_row')continue;const cols=h.table_row.cells.map(text);if(cols[0]!=='測定項目'||cols[1]!=='実測値')continue;const values=[],seen=new Set();for(const row of rows.slice(1)){const c=row.table_row?.cells?.map(text)||[],label=c[0],m=/^(\d{1,3}(?:\.\d+)?)\s*cm$/i.exec(c[1]||'');if(!labels.includes(label)||!m||seen.has(label)||+m[1]<=0||+m[1]>300)continue;seen.add(label);values.push([label,+m[1],date(c[2])])}return values}return []}
 async function discover(){const self=await get('self');const source=self.parent?.data_source_id;if(!goodId(source))throw Error('既存YOS Tasks未確認');const p={self},keys=['plan','body','basic','day30','day60','day90','skin'];try{const q=await api('data_sources/'+source+'/query','POST',{page_size:100,filter:{or:keys.map(k=>({property:'やること',title:{equals:titles[k]}}))}});if(!Array.isArray(q.results)||q.has_more!==false)throw Error('対象一覧未確認');for(const k of keys){const rows=q.results.filter(x=>x.object==='page'&&!x.archived&&!x.in_trash&&goodId(x.id)&&norm(x.parent?.data_source_id)===norm(source)&&pageTitle(x)===titles[k]);if(rows.length===1)p[k]=rows[0]}}catch{};try{p.inbox=await get('inbox')}catch{};
 const config={source,self:self.id,inbox:p.inbox?.id||'',tasks:['basic','day30','day60','day90'].map(k=>p[k]?.id).filter(Boolean)};let values=[];if(p.body)try{values=await measurements(p.body)}catch{};const links=Object.fromEntries(Object.entries(p).map(([k,v])=>[k,'https://app.notion.com/p/'+norm(v.id)]));return {config,profile:{links,dates:dates(p),values,bodyCount:values.length,bodyRead:values.length>0}};}
 return {discover,dates,measurements};
}
