function nativePhotoIO(){const fm=FileManager.local(),root=fm.joinPath(fm.documentsDirectory(),'Self Photo Originals V1');if(!fm.fileExists(root))fm.createDirectory(root,true);const dir=id=>fm.joinPath(root,id),file=id=>fm.joinPath(dir(id),'original.bin'),meta=id=>fm.joinPath(dir(id),'metadata.json');return {ids:()=>fm.listContents(root),hasId:id=>fm.fileExists(dir(id)),create:id=>fm.createDirectory(dir(id),false),exists:id=>fm.fileExists(file(id)),meta:id=>fm.fileExists(meta(id))?JSON.parse(fm.readString(meta(id))):null,writeMeta:(id,m)=>fm.writeString(meta(id),JSON.stringify(m)),write:(id,b64)=>fm.write(file(id),Data.fromBase64String(b64)),read:id=>fm.read(file(id)).toBase64String(),byteLength:b64=>b64.length/4*3-(b64.endsWith('==')?2:b64.endsWith('=')?1:0)}}
const TOKEN_KEY='YOS_NOTION_INTEGRATION_TOKEN';
async function main(){
 const token=Keychain.contains(TOKEN_KEY)?Keychain.get(TOKEN_KEY):'';
 async function api(path,method='GET',body){if(!token)throw Error('既存Notion接続未取得');const req=new Request('https://api.notion.com/v1/'+path);req.method=method;req.timeoutInterval=15;req.headers={Authorization:'Bearer '+token,'Notion-Version':'2025-09-03','Content-Type':'application/json'};if(body!==undefined)req.body=JSON.stringify(body);const data=await req.loadJSON();if(!req.response||req.response.statusCode<200||req.response.statusCode>=300||!data||typeof data!=='object')throw Error('Notion応答未確認');return data}
 let bridge=null,writer=null,profile=null,lastConfig=null;const discovery=createSelfDiscovery(api);const photos=createPhotoStore(nativePhotoIO()),w=new WebView();async function route(req){if(req.action.startsWith('photo-'))return photos.perform(req);if(req.action==='refresh'){try{const result=await discovery.discover();profile=result.profile;const cfg=result.config;if(!bridge||JSON.stringify(cfg)!==lastConfig){bridge=createSelfBridge(api,cfg);writer=createSelfCaptureWriter(api,cfg,bridge);lastConfig=JSON.stringify(cfg);}const data=await bridge.refresh();if(cfg.tasks.length<4)data.taskErrors+=4-cfg.tasks.length;return {action:'refresh',data:{...data,profile}}}catch{bridge=null;writer=null;return {action:'refresh',data:{tasks:[],taskErrors:4,captures:[],inboxOK:false,profile:{links:{},dates:null,values:[]}}}}}if(!bridge||!writer)throw Error('Notion未取得');return req.action==='save-capture'?{action:'save-capture',...await writer.save(req)}:await bridge.perform(req)}await w.loadHTML(HTML);await w.evaluateJavaScript('window.SELF_ENABLE(true)',false);let closed=false;const listen=()=>w.evaluateJavaScript('window.SELF_WAIT(v=>completion(JSON.stringify(v)))',true).then(v=>({kind:'request',v}),()=>({kind:'error'}));let pending=listen();const shown=w.present(false).then(()=>{closed=true;return{kind:'closed'}});while(!closed){const next=await Promise.race([pending,shown]);if(next.kind!=='request')break;let result,req;try{req=JSON.parse(next.v);const payload=await route(req);result={ok:true,...payload}}catch(e){result={ok:false,error:String(e.message||'未確認').slice(0,120)}}if(req?.rpcId)result.rpcId=req.rpcId;if(closed)break;await w.evaluateJavaScript('window.SELF_REPLY('+JSON.stringify(result).replace(/</g,'\\u003c')+')',false);pending=listen()}await shown;
}
try{await main()}catch(e){const a=new Alert();a.title='Self｜未確認';a.message=String(e.message||'エラー');a.addAction('閉じる');await a.presentAlert()}finally{Script.complete()}
